import * as React from 'react';
import GradualBlur from './GradualBlur';
export default function DocumentedDemo(){

return <div style={{width:'100%',minHeight:'100vh',display:'grid',placeItems:'center',position:'relative',padding:24}}><section style={{ position: 'relative', height: 500, overflow: 'hidden' }}>
