return <div style={{width:'100%',minHeight:'100vh',display:'grid',placeItems:'center',position:'relative',padding:24}}><SwipeToast
  open={open}
  onClose={reason => setOpen(false)}
  title="File archived"
  description="Moved to Archive"
  actionLabel="Undo"
  onAction={() => restore()}
  background="#27272a"
  color="#f5f5f5"
  fuseColor="#f5a524"
  width={356}
  radius={12}
  slideMs={400}
  settleBounce={0.2}
  swipeDistance={40}
  duration={4000}
  fuse="bottom"
  pauseOnHover
  closeButton={false}
/>
